package main

import (
	"fmt"
	"os"
)

func main() {
	// Example of checking file type
	fileName := "example.zip"
	if err := checkFileType(fileName); err != nil {
		fmt.Println(err)
	} else {
		fmt.Println("File type is valid.")
	}
}

func checkFileType(fileName string) error {
	if len(fileName) < 4 || fileName[len(fileName)-4:] != ".zip" {
		return fmt.Errorf("invalid file type: %s", fileName)
	}
	return nil
}
